/* ============================================================================
 * CPU execution plans
 * ============================================================================
 */

/** @brief Persistent bounded worker pool used by sealed CPU plans. */
typedef struct magic2_cpu_executor magic2_cpu_executor;

/** @brief Immutable exact-shape tiled CPU execution plan. */
typedef struct magic2_cpu_plan magic2_cpu_plan;

/** @brief Adaptive owner for equivalent exact-shape CPU plans. */
typedef struct magic2_cpu_family magic2_cpu_family;

/** @brief Owning handle for one asynchronously executing CPU plan. */
typedef struct magic2_cpu_ticket magic2_cpu_ticket;

#ifndef MAGIC2_CPU_MAX_WORKERS
#define MAGIC2_CPU_MAX_WORKERS 256u
#endif

/**
 * @brief Execute one logical half-open tile.
 *
 * @details
 * The port array contains the exact addresses derived from the plan shape and
 * current region binding. A slot never executes two callbacks concurrently,
 * so its scratch span is exclusive for the duration of the callback. The
 * callback must not retain the port array or scratch after it returns.
 */
typedef int (*magic2_cpu_tile_fn)(
    const void *environment, void *const *ports, size_t begin, size_t end,
    uint32_t slot, void *scratch);

#define MAGIC2_CPU_SCHEDULE_STATIC  UINT32_C(1)
#define MAGIC2_CPU_SCHEDULE_DYNAMIC UINT32_C(2)
#define MAGIC2_CPU_SCHEDULE_CALLER  UINT32_C(3)

#define MAGIC2_CPU_PLAN_EMPTY_IS_NOOP       UINT32_C(0x00000001)
#define MAGIC2_CPU_PLAN_ALLOW_PARTIAL_FAILURE UINT32_C(0x00000002)
#define MAGIC2_CPU_PLAN_FLAGS_ALL \
    (MAGIC2_CPU_PLAN_EMPTY_IS_NOOP | \
     MAGIC2_CPU_PLAN_ALLOW_PARTIAL_FAILURE)

#define MAGIC2_CPU_EXECUTOR_AUTO_WORKERS UINT32_C(0x00000001)
#define MAGIC2_CPU_EXECUTOR_PIN_WORKERS  UINT32_C(0x00000002)
#define MAGIC2_CPU_EXECUTOR_FLAGS_ALL \
    (MAGIC2_CPU_EXECUTOR_AUTO_WORKERS | MAGIC2_CPU_EXECUTOR_PIN_WORKERS)

#define MAGIC2_CPU_RESOURCE_ONLINE_VALID  UINT32_C(0x00000001)
#define MAGIC2_CPU_RESOURCE_ALLOWED_VALID UINT32_C(0x00000002)
#define MAGIC2_CPU_RESOURCE_QUOTA_VALID   UINT32_C(0x00000004)
#define MAGIC2_CPU_RESOURCE_GROUPS_VALID  UINT32_C(0x00000008)
#define MAGIC2_CPU_RESOURCE_NUMA_VALID    UINT32_C(0x00000010)

#define MAGIC2_CPU_RUN_COMPLETE UINT32_C(1)
#define MAGIC2_CPU_RUN_FAILED   UINT32_C(2)
#define MAGIC2_CPU_RUN_PENDING  UINT32_C(3)
#define MAGIC2_CPU_RUN_CANCELLED UINT32_C(4)

/** @brief OS CPU location copied into a pinned executor at creation. */
typedef struct magic2_cpu_location {
    uint16_t group;       /**< Windows processor group; zero on Linux. */
    uint16_t reserved16;  /**< Reserved; initialize to zero. */
    uint32_t number;      /**< Processor number in the group or Linux CPU ID. */
    uint32_t numa_node;   /**< Caller topology metadata; UINT32_MAX if unknown. */
    uint32_t flags;       /**< Reserved; initialize to zero. */
} magic2_cpu_location;

/** @brief Construction parameters for an owned persistent CPU executor. */
typedef struct magic2_cpu_executor_config {
    uint32_t tag;         /**< ::MAGIC2_TAG_CPU_EXECUTOR. */
    uint32_t struct_size; /**< Size of this descriptor in bytes. */
    uint32_t max_workers; /**< Worker count or AUTO upper bound; zero selects recommended. */
    uint32_t flags;       /**< MAGIC2_CPU_EXECUTOR_* policy flags. */
    const magic2_cpu_location *locations; /**< Optional exact worker placements. */
    uint32_t location_count; /**< Available location descriptors. */
    uint32_t reserved;       /**< Reserved; initialize to zero. */
} magic2_cpu_executor_config;

/** @brief Stable properties of a live CPU executor. */
typedef struct magic2_cpu_executor_info {
    uint32_t tag;            /**< ::MAGIC2_TAG_CPU_EXECUTOR. */
    uint32_t struct_size;    /**< Size of this descriptor in bytes. */
    uint32_t max_workers;    /**< Number of owned worker slots. */
    uint32_t flags;          /**< Active execution policy flags. */
    uint64_t common_features;/**< CPU features observed on every owned worker. */
    uint64_t domain_id;      /**< Process-local executor domain identity. */
    uint64_t domain_epoch;   /**< Domain generation fixed for this executor. */
} magic2_cpu_executor_info;

/** @brief Process-visible CPU capacity used for conservative worker sizing. */
typedef struct magic2_cpu_resource_info {
    uint32_t tag;                /**< ::MAGIC2_TAG_CPU_EXECUTOR. */
    uint32_t struct_size;        /**< Size of this descriptor in bytes. */
    uint32_t valid_flags;        /**< MAGIC2_CPU_RESOURCE_* validity bits. */
    uint32_t online_cpus;        /**< Online logical CPUs reported by the OS. */
    uint32_t allowed_cpus;       /**< CPUs in the current effective affinity. */
    uint32_t processor_groups;   /**< Windows processor groups, otherwise one. */
    uint32_t numa_nodes;         /**< Online NUMA nodes when discoverable. */
    uint32_t recommended_workers;/**< Quota- and affinity-bounded worker count. */
    uint32_t reserved;           /**< Reserved; initialize to zero. */
    uint64_t quota_millicpus;    /**< Tightest visible CPU quota in 1/1000 CPU. */
} magic2_cpu_resource_info;

/** @brief Exact shape, partition, native callback, and ownership for a CPU plan. */
typedef struct magic2_cpu_plan_spec {
    uint32_t tag;              /**< ::MAGIC2_TAG_CPU_PLAN. */
    uint32_t struct_size;      /**< Size of this descriptor in bytes. */
    uint32_t flags;            /**< MAGIC2_CPU_PLAN_* execution contracts. */
    uint32_t schedule;         /**< Static or dynamic tile assignment. */
    magic2_key128 stable_id;   /**< Portable identity for this exact strategy. */
    magic2_shape shape;        /**< Exact operation shape copied into the plan. */
    magic2_cpu_tile_fn tile;   /**< Native tile entry point. */
    const void *environment;   /**< Immutable callback environment. */
    size_t environment_bytes;  /**< Accessible environment extent. */
    magic2_owner owner;        /**< State lifetime retained by the plan. */
    size_t grain;              /**< Positive logical work items per tile. */
    uint32_t worker_limit;     /**< Maximum concurrently active worker slots. */
    uint32_t failure_contract; /**< Overall plan failure visibility contract. */
    magic2_storage per_slot_scratch; /**< Exclusive scratch required by each slot. */
    uint64_t required_cpu_features;  /**< Features required on every execution worker. */
    uint64_t forbidden_cpu_features; /**< Features forbidden on every execution worker. */
} magic2_cpu_plan_spec;

/** @brief Immutable CPU plan metadata and caller-workspace requirements. */
typedef struct magic2_cpu_plan_info {
    uint32_t tag;              /**< ::MAGIC2_TAG_CPU_PLAN. */
    uint32_t struct_size;      /**< Size of this descriptor in bytes. */
    uint32_t flags;            /**< Copied plan contract flags. */
    uint32_t schedule;         /**< Copied tile scheduling policy. */
    magic2_key128 stable_id;   /**< Strategy identity captured by the plan. */
    magic2_key128 operation_id;/**< Exact operation identity. */
    magic2_key128 semantic_id; /**< Exact numerical and semantic identity. */
    size_t count;              /**< Exact logical work count. */
    size_t grain;              /**< Logical work items per tile. */
    size_t tile_count;         /**< Number of callbacks in a successful activation. */
    uint32_t port_count;       /**< Number of ordered callback ports. */
    uint32_t region_count;     /**< Number of caller-supplied regions. */
    uint32_t worker_limit;     /**< Maximum concurrently active slots. */
    uint32_t failure_contract; /**< Overall failure visibility contract. */
    magic2_storage per_slot_scratch; /**< Exclusive storage required per active slot. */
    magic2_storage workspace;  /**< Caller storage required by ::magic2_cpu_plan_run. */
    uint64_t required_cpu_features;  /**< Required common executor features. */
    uint64_t forbidden_cpu_features; /**< Excluded executor features. */
} magic2_cpu_plan_info;

/** @brief Result of one drained CPU plan activation. */
typedef struct magic2_cpu_run_status {
    uint32_t tag;           /**< ::MAGIC2_TAG_CPU_RUN. */
    uint32_t struct_size;   /**< Size of this descriptor in bytes. */
    uint32_t state;         /**< Complete or failed terminal state. */
    uint32_t used_workers;  /**< Worker slots admitted for this activation. */
    size_t completed_tiles; /**< Callbacks that returned success. */
    size_t total_tiles;     /**< Tiles defined by the exact plan. */
    size_t failed_tile;     /**< First observed failing tile, or SIZE_MAX. */
    int runtime_status;     /**< magic2 runtime result. */
    int implementation_status; /**< First observed callback failure. */
} magic2_cpu_run_status;

/** @brief Caller-owned binding that retains one CPU plan. */
typedef struct magic2_cpu_frame {
    uint32_t tag;          /**< ::MAGIC2_TAG_CPU_PLAN. */
    uint32_t struct_size;  /**< Size of this object in bytes. */
    uint32_t state;        /**< Private atomic lifecycle state; do not modify. */
    uint32_t reserved;     /**< Reserved; initialize to zero. */
    uint64_t _cookie;      /**< Private integrity marker; do not copy or modify. */
    void *workspace;       /**< Caller storage fixed by frame initialization. */
    size_t workspace_bytes;/**< Accessible caller storage extent. */
    magic2_cpu_plan *_plan;/**< Private retained plan reference. */
    void **_ports;         /**< Private bound port array in workspace. */
    unsigned char *_scratch; /**< Private slot scratch base in workspace. */
} magic2_cpu_frame;

/** @brief Bounded online-selection policy for an exact CPU plan family. */
typedef struct magic2_cpu_family_config {
    uint32_t tag;             /**< ::MAGIC2_TAG_CPU_PLAN. */
    uint32_t struct_size;     /**< Size of this descriptor in bytes. */
    uint32_t bucket_count;    /**< Number of caller-selected context buckets. */
    uint32_t initial_samples; /**< Successful observations required per plan. */
    uint32_t exploration_interval; /**< Calls between bounded re-exploration. */
    uint32_t ewma_alpha_permille;  /**< New-sample weight from 1 through 1000. */
    uint32_t switch_hysteresis_permille; /**< Required advantage before switching. */
    uint32_t resource_slack_permille; /**< Fastest-plan slack favoring fewer slots. */
    uint32_t import_sample_cap; /**< Maximum prior weight accepted per record. */
    uint32_t flags;           /**< Reserved; initialize to zero. */
} magic2_cpu_family_config;

/** @brief Per-call resource and workload context for family selection. */
typedef struct magic2_cpu_context {
    uint32_t tag;          /**< ::MAGIC2_TAG_CPU_RUN. */
    uint32_t struct_size;  /**< Size of this descriptor in bytes. */
    uint32_t bucket;       /**< Context bucket index selected by the caller. */
    uint32_t slot_budget;  /**< Maximum plan worker limit; zero uses executor maximum. */
    uint32_t flags;        /**< Reserved; initialize to zero. */
    uint32_t reserved;     /**< Reserved; initialize to zero. */
} magic2_cpu_context;

/** @brief Stable capacity and workspace requirements of a CPU family. */
typedef struct magic2_cpu_family_info {
    uint32_t tag;          /**< ::MAGIC2_TAG_CPU_PLAN. */
    uint32_t struct_size;  /**< Size of this descriptor in bytes. */
    uint32_t plan_count;   /**< Number of equivalent owned plans. */
    uint32_t bucket_count; /**< Number of independent policy buckets. */
    magic2_key128 operation_id; /**< Shared exact operation identity. */
    magic2_key128 semantic_id;  /**< Shared exact semantic identity. */
    size_t count;          /**< Shared exact logical work count. */
    magic2_storage workspace; /**< Storage sufficient for every family plan. */
} magic2_cpu_family_info;

/** @brief Selection, fallback, observation, and native result for one call. */
typedef struct magic2_cpu_family_status {
    uint32_t tag;            /**< ::MAGIC2_TAG_CPU_RUN. */
    uint32_t struct_size;    /**< Size of this descriptor in bytes. */
    uint32_t selected_index; /**< Plan chosen by the policy. */
    uint32_t executed_index; /**< Plan actually executed after admission fallback. */
    uint32_t fallback_used;  /**< Whether an idle caller plan replaced a busy plan. */
    uint32_t observation_valid; /**< Whether elapsed_ns was recorded. */
    uint64_t elapsed_ns;     /**< End-to-end plan execution observation. */
    magic2_key128 stable_id; /**< Identity of the executed plan. */
    magic2_cpu_run_status run; /**< Drained native execution result. */
} magic2_cpu_family_status;

/** @brief Learned evidence for one plan in one context bucket. */
typedef struct magic2_cpu_evidence {
    uint32_t tag;          /**< ::MAGIC2_TAG_CPU_RUN. */
    uint32_t struct_size;  /**< Size of this descriptor in bytes. */
    uint32_t plan_index;   /**< Family plan index represented by this result. */
    uint32_t bucket;       /**< Context bucket represented by this result. */
    uint32_t selected;     /**< Whether the policy currently prefers this plan. */
    uint32_t reserved;     /**< Reserved; initialize to zero. */
    uint64_t samples;      /**< Successful timed executions incorporated. */
    uint64_t local_samples;/**< Successful observations measured in this process. */
    uint64_t imported_samples; /**< Bounded warm-start prior weight. */
    uint64_t ewma_ns;      /**< Current end-to-end latency estimate. */
    uint64_t local_ewma_ns;/**< Estimate derived only from local observations. */
    uint64_t failures;     /**< Native failures that disabled this plan. */
} magic2_cpu_evidence;

/** @brief Result counts from importing portable CPU-family evidence. */
typedef struct magic2_cpu_profile_import_result {
    uint32_t tag;          /**< ::MAGIC2_TAG_CPU_PROFILE. */
    uint32_t struct_size;  /**< Size of this descriptor in bytes. */
    uint32_t imported_records; /**< Records matched and incorporated. */
    uint32_t skipped_records;  /**< Unknown, failed, or zero-weight records. */
} magic2_cpu_profile_import_result;

