#define MAGIC2_INTERNAL_FETCH_SUB32(p_, v_) ((uint32_t)InterlockedExchangeAdd((volatile LONG *)(p_), -(LONG)(v_)))
#define MAGIC2_INTERNAL_FETCH_ADD64(p_, v_) ((uint64_t)InterlockedExchangeAdd64((volatile LONG64 *)(p_), (LONG64)(v_)))
#define MAGIC2_INTERNAL_FETCH_ADD64_RELAXED(p_, v_) MAGIC2_INTERNAL_FETCH_ADD64((p_), (v_))
#define MAGIC2_INTERNAL_FETCH_SUB64(p_, v_) ((uint64_t)InterlockedExchangeAdd64((volatile LONG64 *)(p_), -(LONG64)(v_)))
