static inline void magic2_internal_test_lock_counters_reset(void) {
    MAGIC2_INTERNAL_STORE64_RELAXED(&magic2_internal_test_park_waits, 0u);
    MAGIC2_INTERNAL_STORE64_RELAXED(&magic2_internal_test_park_wakes, 0u);
    MAGIC2_INTERNAL_STORE64_RELAXED(&magic2_internal_test_fallback_sleeps, 0u);
}
